import {Catalog} from './lib/catalog.js';
import {read,write,deleteLocalData} from './lib/storage.js';
import {money,parseMoney,price,linePrice,totals,budgetStatus,savings,today,tripCsv,monthlyInsight,WARNING,normalizeText} from './lib/core.js';
import {icon,categoryIcon,basketArt} from './lib/icons.js';
import {strings} from './i18n.js';

const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const catalog=new Catalog();
let S={cart:[],budget:null,trips:[],lists:[{id:'next',name:'My next shop',items:[]}],activeList:'next',dismissed:[],theme:'system',language:'en',welcomed:false,aiConsent:false,savingsFound:0};
let tab='shop',query='',category='',department='groceries',searchTimer,scanner,torch=false,lastResult=null,toastTimer,installPrompt,chat=[],lastBudgetState='unset',searchLimit=24,account=null;
const t=key=>strings[S.language]?.[key]||strings.en[key]||key;
const navKeys=['shop','cart','savings','lists','trips','ask','settings'];
const formatDate=value=>value?new Intl.DateTimeFormat(S.language==='fil'?'fil-PH':'en-PH',{day:'numeric',month:'short',year:'numeric'}).format(new Date(value)):'No published prices';
const priceDate=p=>p.priceAsOf?`Prices as of ${p.priceAsOf}`:'Price date unavailable';
function applyTheme(){document.documentElement.dataset.theme=S.theme==='system'?(matchMedia('(prefers-color-scheme:dark)').matches?'dark':'light'):S.theme;document.documentElement.lang=S.language==='fil'?'fil':'en';}
function notify(message,undo){clearTimeout(toastTimer);$('#toast').innerHTML=`<div class="toast-inner">${icon('check')}<span>${esc(message)}</span>${undo?'<button id="undo-toast">Undo</button>':''}</div>`;if(undo)$('#undo-toast').onclick=()=>{undo();$('#toast').replaceChildren();};toastTimer=setTimeout(()=>$('#toast').replaceChildren(),5500);}
async function save(){try{await write('user',S);}catch{notify('Changes could not be saved. Device storage may be full.');}}
const currentList=()=>S.lists.find(l=>l.id===S.activeList)||S.lists[0];
function navButton(key,mobile=false){return `<button class="${mobile?'':'nav-button '}${tab===key?'active':''}" data-tab="${key}" ${tab===key?'aria-current="page"':''}>${icon(key)}<span>${esc(t(key))}</span>${key==='cart'&&S.cart.length?`<${mobile?'i':'span'} class="${mobile?'count':'badge'}">${totals(S.cart).count}</${mobile?'i':'span'}>`:''}</button>`;}
function shell(){
 $('#app').innerHTML=`<aside class="sidebar"><a href="#shop" class="brand" aria-label="FUJI Grocery Tracker home"><span class="brand-symbol">F<span>•</span></span><span><b class="brand-word">FUJI</b><small>GROCERY TRACKER</small></span></a><p class="nav-caption">YOUR SHOPPING COMPANION</p><nav class="desktop-nav" aria-label="Main navigation">${navKeys.map(k=>navButton(k)).join('')}</nav><div class="sidebar-bottom"><div class="local-note">${icon('lock')}<b>A little peace of mind.</b>Your trips and lists stay on this device. No login needed.</div><a class="system-link" href="/">FUJI Cycle Count System ${icon('arrow')}</a></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb">Your workspace <span>/</span> <b id="breadcrumb">${esc(t(tab))}</b></div><div class="mobile-brand"><a href="#shop" class="brand"><span class="brand-symbol">F<span>•</span></span><span><b class="brand-word">FUJI</b><small>GROCERY TRACKER</small></span></a></div><div class="top-actions"><span id="connection" class="status ${navigator.onLine?'':'offline'}"><span class="status-dot"></span>${navigator.onLine?'Ready to shop':'Offline mode'}</span><button class="icon-button" data-action="history" aria-label="Past trips">${icon('trips')}</button><button class="icon-button" data-tab="ask" aria-label="Ask FUJI">${icon('ask')}</button><button class="icon-button" data-action="theme" aria-label="Toggle light or dark theme">${icon(document.documentElement.dataset.theme==='dark'?'sun':'moon')}</button><button class="icon-button" data-tab="settings" aria-label="Open settings">${icon('settings')}</button><span class="avatar" aria-label="Guest shopper">YOU</span></div></header><main id="main" class="content" tabindex="-1"></main></div><div id="mobile-total" aria-live="polite" aria-atomic="true"></div><nav class="mobile-nav" aria-label="Mobile navigation">${navButton('shop',true)}${navButton('lists',true)}<button class="scan-nav" data-action="scan" aria-label="Scan a product barcode"><span>${icon('scan')}</span>${esc(t('scan'))}</button>${navButton('cart',true)}${navButton('savings',true)}</nav>`;
 renderPage();
}
function title(kicker,heading,copy,action=''){return `<div class="page-title"><div><p class="eyebrow">${kicker}</p><h1>${heading}</h1><p>${copy}</p></div>${action||`<div class="date-pill">${icon('leaf')} A little smarter, every shop.</div>`}</div>`;}
function warning(){return `<div class="notice price-warning">${icon('warning')}<p><b>${S.language==='fil'?'Tantiya lamang ang presyo.':'A friendly price reminder.'}</b>${esc(t('warning'))}</p></div>`;}
function budgetCard(){const v=totals(S.cart),b=budgetStatus(v.knownCentavos,S.budget);return `<section class="side-card ${b.state}"><div class="card-kicker">${esc(t('budget'))}<button class="text-button" data-action="budget" aria-label="Edit trip budget">Edit</button></div><div class="budget-amount">${S.budget?money(S.budget):'Set a budget'}${S.budget?'<small> this trip</small>':''}</div><div class="progress" role="progressbar" aria-label="Known subtotal compared with budget" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.min(100,Math.round(b.ratio*100))}"><span style="width:${Math.min(100,b.ratio*100)}%"></span></div><div class="budget-status">${icon(b.state==='over'?'warning':b.state==='near'?'info':'check')} ${esc(b.label)}</div>${v.unpricedQuantity?`<p class="hint">+ ${v.unpricedQuantity} unpriced item(s). Budget status is provisional.</p>`:''}<div class="budget-bottom"><p>${b.remaining==null?'Known subtotal':b.remaining<0?'Over by (known prices)':'Left from known prices'}</p><strong>${money(b.remaining==null?v.knownCentavos:Math.abs(b.remaining))}</strong></div></section>`;}
function basketAside(){const v=totals(S.cart);return `<aside class="basket-aside">${budgetCard()}<section class="side-card"><div class="mini-title"><h2>Your basket</h2><span class="count-badge">${v.count} item${v.count===1?'':'s'}</span></div>${S.cart.length?S.cart.slice(-3).map(l=>`<div class="mini-line"><div><p>${esc(l.product.name)}</p><span>Qty ${l.quantity}</span></div><strong>${linePrice(l)==null?'Unpriced':money(linePrice(l)*l.quantity)}</strong></div>`).join(''):`<div class="mini-empty"><span>${icon('bag')}</span><p>Good things start here.</p><small>Scan or add your first item.</small></div>`}<div class="mini-totals"><span>${esc(t('subtotal'))}</span><strong>${money(v.knownCentavos)}</strong></div>${v.unpricedQuantity?`<p class="hint">${v.unpricedQuantity} item(s) need a shelf price.</p>`:''}<button class="btn ${S.cart.length?'primary':'secondary'} full" data-action="${S.cart.length?'view-basket':'scan'}">${icon(S.cart.length?'cart':'scan')}${S.cart.length?'View your basket':'Scan your first item'}${icon('arrow')}</button><p class="as-of">${catalog.priceAsOf?'Catalog updated '+formatDate(catalog.priceAsOf):'Supplied price list · Price date unavailable'}</p></section><div class="side-tip">${icon('leaf')}<div><h3>Small habits. Better baskets.</h3><p>Make a list before you go. A little planning helps you keep the essentials in and the extras in check.</p></div></div><p class="sidebar-footer">Made for everyday shopping. Made for you.</p></aside>`;}
function renderPage(){
 const main=$('#main');
 if(tab==='shop')main.innerHTML=shopPage();
 if(tab==='cart')main.innerHTML=cartPage();
 if(tab==='lists')main.innerHTML=listsPage();
 if(tab==='savings')main.innerHTML=savingsPage();
 if(tab==='trips')main.innerHTML=tripsPage();
 if(tab==='settings')main.innerHTML=settingsPage();
 if(tab==='ask')main.innerHTML=askPage();
 $('#breadcrumb').textContent=t(tab);
 if(tab==='shop')renderProducts();
 updatePinned();
}
function updatePinned(){const v=totals(S.cart);$('#mobile-total').innerHTML=`<div class="mobile-total"><div><p>${esc(t('subtotal'))} · ${v.count} item${v.count===1?'':'s'}${v.unpricedQuantity?` + ${v.unpricedQuantity} unpriced`:''}</p><strong>${money(v.knownCentavos)}</strong><small>Estimate only · Final prices at cashier</small></div><button data-action="${S.cart.length?'view-basket':'budget'}">${S.cart.length?'View basket':S.budget?'Edit budget':'Set budget'} ${icon('arrow')}</button></div>`;document.querySelectorAll('.desktop-nav [data-tab=cart],.mobile-nav [data-tab=cart]').forEach(b=>{let badge=b.querySelector('.badge,.count');if(v.count){if(!badge){badge=document.createElement('span');badge.className=b.closest('.mobile-nav')?'count':'badge';b.append(badge);}badge.textContent=String(v.count);}else badge?.remove();});document.querySelectorAll('[data-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.tab===tab);if(b.dataset.tab===tab)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});}
function shopPage(){
 const popular=[['','All items'],['STAPLE','Staples'],['MILK AND DAIRY','Dairy'],['SNACK FOODS','Snacks'],['COOKING ESSENTIALS','Cooking'],['HOUSEHOLD CARE','Home care']];
 return title('EVERYDAY SHOPPING, A LITTLE SMARTER',S.language==='fil'?'Bawat piso, sulit.':'Every peso, well spent.',esc(t('subtitle')))+`<div class="page-grid"><div class="main-column"><section class="hero"><div class="hero-copy"><p class="eyebrow">YOUR BUDGET. IN THE BAG.</p><h2>${S.language==='fil'?'Planadong bili. Mas sulit na basket.':'A little planning.<br>A better basket.'}</h2><p>Scan your finds. Know your spend.<br>Bring home a little peace of mind.</p><button class="btn primary" data-action="scan">${icon('scan')} Let’s start scanning ${icon('arrow')}</button></div>${basketArt}</section><div class="section-head"><h2>What’s on your list?</h2><span class="small">Hypermart catalog</span></div><div class="searchbox"><label class="sr-only" for="product-search">${esc(t('search'))}</label>${icon('search')}<input id="product-search" type="search" placeholder="${esc(t('search'))}" value="${esc(query)}" autocomplete="off" enterkeyhint="search"><button data-action="lookup-search" aria-label="Look up entered barcode">${icon('scan')}</button></div><div class="filter-row"><label class="sr-only" for="department-filter">Department</label><select id="department-filter"><option value="groceries" ${department==='groceries'?'selected':''}>Grocery departments</option><option value="all" ${department==='all'?'selected':''}>All listed items</option>${catalog.meta.departments.map(d=>`<option value="${esc(d)}" ${d===department?'selected':''}>${esc(d)}</option>`).join('')}</select><label class="sr-only" for="category-filter">Category</label><select id="category-filter"><option value="">All categories</option>${catalog.meta.categories.map(c=>`<option ${category===c?'selected':''} value="${esc(c)}">${esc(c)}</option>`).join('')}</select></div><div class="categories" aria-label="Quick categories">${popular.map(([value,label])=>`<button class="chip ${category===value?'active':''}" data-category="${value}" aria-pressed="${category===value}">${icon(categoryIcon(value))}${label}</button>`).join('')}</div><div class="result-meta"><span id="result-count">Finding your everyday essentials…</span><span>Your supplied items and prices.</span></div><div id="products" class="products">${'<div class="skeleton"></div>'.repeat(4)}</div><div id="more-products"></div><div class="catalog-note">${icon('info')}<span>${catalog.meta.itemCount.toLocaleString()} listed products · Imported ${formatDate(catalog.meta.updatedAt)}.<br>Prices are from your supplied item list, matched by SKU to HYPERMART. The price list has no effective date. Stock is unknown; confirm shelf and cashier prices.</span></div>${warning()}</div>${basketAside()}</div>`;
}
function productCard(p){const v=price(p),original=p.priceCentavos!=null&&v!=null&&v<p.priceCentavos?'<del class="small">'+money(p.priceCentavos)+'</del> ':'';const inCart=S.cart.find(l=>l.product.sku===p.sku);return `<article class="product"><div class="product-top"><div class="product-symbol">${icon(categoryIcon(p.category))}</div><div><p class="product-category">${esc(p.category)}</p><p class="product-sku">SKU ${esc(p.sku)}</p></div></div><h3>${esc(p.name)}</h3><div class="product-footer"><div class="product-price ${v==null?'unknown':''}">${original}${v==null?esc(t('unpriced')):money(v)}${p.promoCentavos===v&&v!=null?'<span class="tag amber">SALE</span>':''}<span class="as-of">${esc(priceDate(p))}</span></div><button class="add-button" data-add="${esc(p.sku)}" aria-label="Add ${esc(p.name)} to basket">${inCart?`<span>${inCart.quantity}</span>`:icon('plus')}</button></div><div class="product-actions"><button data-plan="${esc(p.sku)}">${icon('lists')} Save</button><button data-detail="${esc(p.sku)}">Details ${icon('chevron')}</button></div></article>`;}
function renderProducts(){
 const grid=$('#products');if(!grid)return;
 if((query||category||searchLimit>24||!catalog.starterOnly)&&!catalog.isDepartmentLoaded(department)){
  grid.setAttribute('aria-busy','true');grid.innerHTML='<div class="skeleton"></div>'.repeat(4);$('#result-count').textContent='Opening the full department catalog…';$('#more-products').replaceChildren();
  catalog.loadDepartment(department).then(()=>{if(tab==='shop')renderProducts();}).catch(error=>{grid.setAttribute('aria-busy','false');grid.innerHTML='<p class="hint">Connect to load the full department, then retry your search.</p>';notify(error.message);});return;
 }
 grid.setAttribute('aria-busy','false');
 const products=catalog.search(query,category,searchLimit,department);
 grid.innerHTML=products.length?products.map(productCard).join(''):`<div class="empty">${icon('search')}<h2>No matches just yet.</h2><p>Try a shorter product name, a different category, or look up the full barcode. If it is missing, you can add it privately.</p><button class="btn secondary" data-action="manual">Add a manual item</button></div>`;
 $('#result-count').textContent=`${products.length}${products.length===searchLimit?'+':''} ${query?'matching products':'everyday finds'} · ${department==='groceries'?'Grocery departments':'Hypermart'}`;
 $('#more-products').innerHTML=products.length===searchLimit?'<button class="text-button" data-action="more-products">Show more products '+icon('down')+'</button>':'';
}
function cartPage(){const v=totals(S.cart);return title('YOUR SHOP, AT A GLANCE',esc(t('cart')),'A place for the essentials. A little room for the good stuff.',`<button class="btn secondary" data-action="manual">${icon('plus')} Add manually</button>`)+`<div class="two-column"><div><div class="cart-list">${S.cart.length?S.cart.map(l=>cartLine(l)).join(''):`<div class="empty">${icon('cart')}<h2>Your next good shop starts here.</h2><p>Find an item in the Hypermart catalog or scan its barcode. Your running estimate will appear as you go.</p><button class="btn primary" data-tab="shop">Browse the catalog ${icon('arrow')}</button></div>`}</div>${warning()}</div><aside class="cart-summary">${budgetCard()}<section class="side-card"><h2>Trip summary</h2><div class="summary-row"><span>Items in your basket</span><strong>${v.count}</strong></div>${Object.entries(v.categories).map(([c,n])=>`<div class="summary-row"><span>${esc(c)}</span><strong>${money(n)}</strong></div>`).join('')}<div class="summary-row total"><span>Known subtotal</span><strong>${money(v.knownCentavos)}</strong></div>${v.unpricedQuantity?`<div class="notice">${icon('warning')}<p>${v.unpricedQuantity} item(s) have no price. This is an incomplete estimate.</p></div>`:''}<button class="btn primary full" data-action="finish" ${S.cart.length?'':'disabled'}>${icon('check')} ${esc(t('finish'))}</button><p class="hint">Saves this trip on your device. Final prices are confirmed at the cashier.</p><p class="as-of">${catalog.priceAsOf?'Catalog updated '+formatDate(catalog.priceAsOf):'No published price date. Shelf entries are dated individually.'}</p></section></aside></div>`;}
function cartLine(l){const p=linePrice(l);return `<article class="cart-item ${l.checked?'checked':''}" data-cart-sku="${esc(l.product.sku)}"><div class="product-symbol">${icon(categoryIcon(l.product.category))}</div><div><h3>${esc(l.product.name)}</h3><p class="sku">SKU ${esc(l.product.sku)} · ${esc(l.product.category||'Manual item')}</p><span class="as-of">${l.manualCentavos!=null?'Shelf price entered '+esc(l.observedAt||today()):esc(priceDate(l.product))}</span></div><div class="line-total">${p==null?'Unpriced':money(p*l.quantity)}<div class="small">${p==null?'Needs shelf price':`${money(p)} each`}</div></div><div class="cart-controls"><div class="stepper"><button data-qty="-1" data-sku="${esc(l.product.sku)}" aria-label="Decrease quantity of ${esc(l.product.name)}">${icon('minus')}</button><span aria-label="Quantity">${l.quantity}</span><button data-qty="1" data-sku="${esc(l.product.sku)}" aria-label="Increase quantity of ${esc(l.product.name)}">${icon('plus')}</button></div><button class="text-button" data-price="${esc(l.product.sku)}">${p==null?'Enter shelf price':'Edit shelf price'}</button><button class="icon-button" data-remove="${esc(l.product.sku)}" aria-label="Remove ${esc(l.product.name)}">${icon('trash')}</button></div><div class="cart-extra"><label class="check-item"><input type="checkbox" data-check="${esc(l.product.sku)}" ${l.checked?'checked':''}> In trolley</label><label class="sr-only" for="note-${esc(l.product.sku)}">Item note</label><input id="note-${esc(l.product.sku)}" placeholder="Add a note…" maxlength="200" value="${esc(l.note||'')}" data-note="${esc(l.product.sku)}"></div></article>`;}
function listsPage(){const list=currentList(),remaining=list.items.filter(l=>!l.checked).length;return title('A GOOD SHOP STARTS WITH A LIST',esc(t('lists')),'Plan ahead. Check things off. Keep the extras in check.',`<button class="btn secondary" data-action="new-list">${icon('plus')} New list</button>`)+`<div class="two-column"><div class="wide-card"><div class="section-head"><h2>${esc(list.name)}</h2><span class="count-badge">${remaining} to find</span></div><label class="field">Choose a list<select id="list-select">${S.lists.map(l=>`<option value="${esc(l.id)}" ${l.id===list.id?'selected':''}>${esc(l.name)}</option>`).join('')}</select></label>${list.items.length?list.items.map(l=>`<div class="list-row"><div class="list-line-main"><input type="checkbox" data-list-check="${esc(l.product.sku)}" aria-label="Check off ${esc(l.product.name)}" ${l.checked?'checked':''}><div><h3 ${l.checked?'style="text-decoration:line-through"':''}>${esc(l.product.name)}</h3><p>SKU ${esc(l.product.sku)} · ${price(l.product)==null?'Price unavailable':money(price(l.product))}</p><span class="as-of">${esc(priceDate(l.product))}</span></div></div><button class="icon-button" data-list-remove="${esc(l.product.sku)}" aria-label="Remove from list">${icon('close')}</button></div>`).join(''):`<div class="empty">${icon('lists')}<h2>A fresh start.</h2><p>Search the catalog and tap “Save to list” on anything you need. Scanning a listed item will check it off.</p><button class="btn primary" data-tab="shop">Find your essentials ${icon('arrow')}</button></div>`}<div class="toolbar"><button class="btn secondary" data-tab="shop">${icon('plus')} Find products</button>${list.items.length?'<button class="btn primary" data-action="list-to-cart">Add unchecked items to basket</button>':''}</div></div><aside><div class="side-tip">${icon('lists')}<div><h3>One less thing to remember.</h3><p>Keep separate lists for your weekly shop, home essentials or your next gathering. Your lists stay on this device.</p></div></div>${warning()}</aside></div>`;}
const pricedProducts=()=>[...catalog.prices.values()].map(p=>catalog.product(catalog.bySku.get(p.sku))||(p.name?p:null)).filter(Boolean);
const allSuggestions=()=>savings(S.cart,pricedProducts(),S.budget,today(),S.dismissed);
function savingsPage(){const suggestions=allSuggestions(),potential=suggestions.reduce((s,x)=>s+x.savedCentavos,0);return title('LITTLE CHANGES, MORE LEFT OVER',esc(t('savings')),'Useful suggestions, with the numbers to back them up.')+`<div class="savings-hero">${icon('leaf')}<div><p>POTENTIAL BASKET SAVINGS</p><h2>${money(potential)}</h2><p>${catalog.prices.size?'Only verified prices, pack sizes and comparison groups are used.':'Waiting for verified prices and net sizes from the store.'}</p></div></div>${suggestions.length?suggestions.map((s,i)=>`<article class="suggestion"><span class="tag">${esc(s.confidence)}</span>${s.savedCentavos?`<span class="saved">Save ${money(s.savedCentavos)}</span>`:''}<h3>${s.type==='rescue'?'A little breathing room for your budget':s.type==='overlap'?'A possible double-up':esc(s.target.name)}</h3><p>${esc(s.reason)}</p>${s.actions?`<p>${s.actions.map(a=>esc(a.name)+' ('+money(a.centavos)+')').join('<br>')}</p>`:''}<div class="toolbar">${s.savedCentavos?`<button class="btn primary" data-swap="${i}">Use this swap ${icon('arrow')}</button>`:''}${s.type==='rescue'?'<button class="btn secondary" data-tab="cart">Review my basket</button>':`<button class="btn secondary" data-dismiss="${esc(s.id)}">Don’t suggest again</button>`}</div></article>`).join(''):`<div class="empty">${icon('savings')}<h2>Good advice needs good data.</h2><p>Your supplied list includes prices. Verified net sizes, comparison groups and live stock are still missing, so price-per-unit savings cannot be calculated reliably. You can update any price you see on the shelf.</p><a class="btn secondary" href="./templates/price-enrichment.csv" download>${icon('download')} Price enrichment template</a></div>`}<section class="wide-card" style="margin-top:20px"><p class="eyebrow">YOUR SPENDING PATTERNS</p><h2>A little perspective.</h2><p class="hint">${esc(monthlyInsight(S.trips.filter(x=>x.date.slice(0,7)===today().slice(0,7)),pricedProducts()))}</p></section>${warning()}`;}
function tripsPage(){const months=[];const now=new Date();for(let i=5;i>=0;i--){const d=new Date(now.getFullYear(),now.getMonth()-i,1);const key=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0');months.push({key,label:d.toLocaleDateString('en',{month:'short'}),value:S.trips.filter(t=>t.date.startsWith(key)).reduce((n,t)=>n+t.totals.knownCentavos,0)});}const max=Math.max(...months.map(m=>m.value),1),categoryTotals={};for(const trip of S.trips)for(const [c,n] of Object.entries(trip.totals.categories))categoryTotals[c]=(categoryTotals[c]||0)+n;const catMax=Math.max(...Object.values(categoryTotals),1);return title('LOOK BACK. SHOP AHEAD.',esc(t('trips')),'Your everyday spending, a little easier to understand.',`<button class="btn secondary" data-action="export">${icon('download')} Export CSV</button>`)+`<div class="settings-grid"><section class="wide-card"><h2>Your last six months</h2><p class="hint">Known spending from saved trips. Incomplete trips exclude unpriced items.</p><div class="chart-bars" role="img" aria-label="${esc(months.map(m=>m.label+': '+money(m.value)).join(', '))}">${months.map(m=>`<div class="chart-bar" style="height:${Math.max(3,m.value/max*85)}%"><b>${m.value?money(m.value):''}</b><span>${m.label}</span></div>`).join('')}</div></section><section class="wide-card"><h2>Where it goes</h2><p class="hint">All saved trips · Known prices only</p>${Object.entries(categoryTotals).sort((a,b)=>b[1]-a[1]).slice(0,7).map(([c,n])=>`<div class="category-bar"><label>${esc(c)}</label><div><i style="width:${n/catMax*100}%"></i></div><strong>${money(n)}</strong></div>`).join('')||'<p class="hint">Your category breakdown will appear after your first trip.</p>'}</section></div>${S.trips.length?S.trips.slice().reverse().map(trip=>`<section class="wide-card"><div class="section-head"><div><h2>${formatDate(trip.date)}</h2><p class="hint">${trip.totals.count} items · ${trip.totals.complete?'Estimated total':'Incomplete estimate: '+trip.totals.unpricedQuantity+' unpriced'}</p></div><h2 class="money">${money(trip.totals.knownCentavos)}</h2></div><p class="as-of">${esc(trip.priceAsOf?'Catalog prices as of '+trip.priceAsOf:'Price dates are recorded on individual lines.')}</p><div class="toolbar"><button class="btn secondary" data-trip="${esc(trip.id)}">View items</button><button class="btn secondary" data-share="${esc(trip.id)}">${icon('share')} Share summary</button><button class="btn secondary" data-image="${esc(trip.id)}">${icon('download')} Save summary image</button></div></section>`).join(''):`<div class="empty">${icon('trips')}<h2>Your story starts with one shop.</h2><p>Finish a trip from your basket to save its items, spending and category breakdown on this device.</p><button class="btn primary" data-tab="shop">Start a trip ${icon('arrow')}</button></div>`}${warning()}`;}
function settingsPage(){return title('MAKE YOURSELF AT HOME',esc(t('settings')),'Your preferences, your privacy, your pace.')+`<div class="settings-grid"><section class="wide-card"><h2>The little preferences</h2><div class="setting-row"><div><h3>Appearance</h3><p>Follow your device, or choose your own.</p></div><select id="theme-select" aria-label="Theme">${['system','light','dark'].map(x=>`<option ${S.theme===x?'selected':''} value="${x}">${x[0].toUpperCase()+x.slice(1)}</option>`).join('')}</select></div><div class="setting-row"><div><h3>Language / Wika</h3><p>Key navigation and shopping prompts.</p></div><select id="language-select" aria-label="Language"><option value="en" ${S.language==='en'?'selected':''}>English</option><option value="fil" ${S.language==='fil'?'selected':''}>Filipino</option></select></div><div class="setting-row"><div><h3>Currency</h3><p>Philippine peso · integer centavos</p></div><strong>PHP ₱</strong></div><div class="setting-row"><div><h3>Add FUJI to your home screen</h3><p>Open it like an app. Camera access requires HTTPS.</p></div><button class="btn secondary" data-action="install">${icon('download')} Install</button></div><div class="setting-row"><div><h3>Optional account</h3><p id="account-state">${account?'Signed in as '+esc(account.email):'No login needed. Sign in only if cloud sync is configured.'}</p></div><button class="btn secondary" data-action="account">${account?'Account':'Sign in'}</button></div></section><section class="wide-card"><h2>Your Hypermart catalog</h2><div class="summary-row"><span>Reference version</span><b>v${catalog.meta.version}</b></div><div class="summary-row"><span>Hypermart products</span><b>${catalog.meta.itemCount.toLocaleString()}</b></div><div class="summary-row"><span>Published price version</span><b>${catalog.priceVersion?`v${catalog.priceVersion}`:'Not supplied'}</b></div><div class="summary-row"><span>Imported</span><b>${formatDate(catalog.meta.updatedAt)}</b></div><p class="hint">Other sheets are excluded. Vendor details are excluded from the public catalog. Original A/I/N status is not live stock.</p><div class="toolbar"><button class="btn secondary" data-action="refresh">${icon('trips')} Check for new prices</button><button class="btn soft" data-action="download-offline">${icon('download')} Download full catalog</button></div><p id="offline-progress" class="hint">Initial grocery data and visited barcode files are cached. The full reference catalog is about ${Math.ceil(catalog.meta.files.reduce((n,f)=>n+f.bytes,0)/1048576)} MB.</p><button class="text-button" data-action="poster">Print a shopper QR poster ${icon('arrow')}</button></section><section class="wide-card"><h2>Private by default</h2><div class="setting-row"><div><h3>Online Ask FUJI consent</h3><p>Optional. Sends only your question and selected basket summary to the configured server. The local helper works without this.</p></div><input id="ai-consent" type="checkbox" aria-label="Consent to online assistant data sharing" ${S.aiConsent?'checked':''}></div><p class="hint">No ads, tracking pixels or third-party analytics. Camera frames stay on your device. No camera images are uploaded.</p><div class="toolbar"><button class="btn secondary" data-action="privacy">${icon('lock')} Privacy notice</button><button class="btn secondary" data-action="backup">${icon('download')} Download my data</button><button class="btn danger" data-action="delete">${icon('trash')} Delete my data</button></div></section><section class="wide-card"><h2>For store staff</h2><p class="hint">Prices come from your supplied item list. Staff can validate updates, add verified sizes and publish versioned price files from the protected catalog workspace.</p><a class="btn secondary" href="/?shopper-catalog=1">Open FUJI admin ${icon('arrow')}</a><p class="hint">Online publication requires a server-verified administrator and configured GitHub publishing credentials.</p></section></div>${warning()}`;}
function askPage(){return title('A LITTLE HELP GOES A LONG WAY',esc(t('ask')),'Helpful answers grounded in the catalog. No made-up prices.')+`<div class="chat-container"><div class="chat-welcome"><span>${icon('spark')}</span><h2>What’s on your mind?</h2><p>Find an item, check your budget, or think through your basket. The local helper keeps your information on this device.</p><span class="tag">${S.aiConsent&&account?'Online helper enabled':'Private, on-device helper'}</span></div><div class="prompt-chips">${['What’s the cheapest rice?','How is my budget?','What should I remove?','Ano ang mas mura?'].map(q=>`<button data-prompt="${esc(q)}">${esc(q)}</button>`).join('')}</div><div id="chat-log" class="chat-log" aria-live="polite">${chatMessages()}</div><form id="chat-form" class="chat-form"><label class="sr-only" for="chat-input">Ask FUJI a question</label><input id="chat-input" placeholder="Ask about an item or your basket…" maxlength="500" autocomplete="off" required><button class="btn primary" type="submit" aria-label="Send question">${icon('arrow')}</button></form><p class="hint">Local suggestions cost nothing. Optional online AI needs a configured account and explicit consent. ${esc(WARNING)}</p></div>`;}
function chatMessages(){return chat.map(m=>`<div class="message ${m.role}">${m.role==='assistant'?'<b>FUJI · Catalog helper</b>':''}${esc(m.text)}</div>`).join('');}
function navigate(next){if(!navKeys.includes(next))return;tab=next;location.hash=next;renderPage();window.scrollTo({top:0,behavior:'instant'});}
function afterCart(message){const v=totals(S.cart),b=budgetStatus(v.knownCentavos,S.budget);if(lastBudgetState!==b.state&&['near','over'].includes(b.state)){navigator.vibrate?.([80,40,80]);notify(b.state==='over'?'Your known subtotal is over budget. Review your basket in Savings.':'You have reached 80% of your budget.');}else if(message)notify(message);lastBudgetState=b.state;save();renderPage();}
function addProduct(p,quantity=1){const existing=S.cart.find(l=>l.product.sku===p.sku);if(existing){if(existing.quantity+quantity>9999){notify('Maximum quantity is 9,999.');return;}existing.quantity+=quantity;}else S.cart.push({product:p,quantity,manualCentavos:null,note:'',checked:false});const planned=currentList().items.find(l=>l.product.sku===p.sku);if(planned)planned.checked=true;afterCart('Added to your basket.');}
function dialog(heading,body){if(scanner){scanner.stop();scanner=null;}const d=$('#sheet');if(d.open)d.close();d.innerHTML=`<div class="sheet-head"><h2>${heading}</h2><button class="icon-button" data-action="close-sheet" aria-label="Close dialog">${icon('close')}</button></div><div class="sheet-body">${body}</div>`;d.setAttribute('aria-label',heading);d.showModal();return d;}
function closeSheet(){scanner?.stop();scanner=null;$('#sheet').close();}
function showBudget(onboarding=false){dialog(onboarding?'Welcome to a better basket.':'A little room for what matters.',`${onboarding?`<p>A private shopping companion for Hypermart. No account needed.</p><div class="onboarding-cards"><div class="onboarding-card">${icon('lists')}<div><h3>Plan a little.</h3><p>Save a list before you go. Find products from the Hypermart sheet.</p></div></div><div class="onboarding-card">${icon('scan')}<div><h3>Scan as you shop.</h3><p>Camera permission is requested only when you choose to scan. Frames stay on your device.</p></div></div><div class="onboarding-card">${icon('cart')}<div><h3>Keep track of every peso.</h3><p>Use your supplied prices for a running estimate. Update any price that differs on the shelf; final prices are confirmed at the cashier.</p></div></div></div>`:'<p>Choose a budget for this trip. We’ll help you keep an eye on your known spending.</p>'}<form id="budget-form"><label class="field" for="budget-input">${onboarding?'Optional trip budget':'Your trip budget'}</label><div class="input-prefix">₱<input id="budget-input" inputmode="decimal" placeholder="2,000.00" maxlength="15" value="${S.budget?S.budget/100:''}" autocomplete="off"></div><div class="budget-presets">${[500,1000,2000,3000].map(n=>`<button type="button" data-preset="${n}">${money(n*100)}</button>`).join('')}</div><p class="form-error" id="budget-error" role="alert"></p><button class="btn primary full" type="submit">${onboarding?'Let’s make a good shop':'Save my budget'} ${icon('arrow')}</button></form><p class="hint">${esc(WARNING)}</p>`);$('#budget-form').onsubmit=e=>{e.preventDefault();const raw=$('#budget-input').value.trim(),v=raw?parseMoney(raw):null;if(raw&&(v==null||v<=0)){$('#budget-error').textContent='Enter a positive amount with up to two decimal places.';return;}S.budget=v;S.welcomed=true;save();closeSheet();renderPage();notify(v?'Trip budget saved.':'You’re ready. Set a budget any time.');};}
function showManual(product=null){dialog(product?'Enter the shelf price':'Add a private item',`<p>${product?esc(product.name):'Not in the catalog? Add the item and the price you see. It stays on your device.'}</p><form id="manual-form">${product?'':`<label class="field">Item name<input id="manual-name" required maxlength="100" placeholder="Name on the shelf"></label>`}<label class="field">Shelf price (PHP)<input id="manual-price" inputmode="decimal" placeholder="0.00" maxlength="15" required></label><label class="field">Quantity<input id="manual-qty" type="number" min="1" max="9999" step="1" value="${product?S.cart.find(l=>l.product.sku===product.sku)?.quantity||1:1}" required></label><p id="manual-error" class="form-error" role="alert"></p><button class="btn primary full" type="submit">${product?'Save shelf price':'Add to basket'}</button></form><p class="hint">Estimate only. Final prices are confirmed at the cashier. Shelf prices are never published to other shoppers.</p>`);if(product){const line=S.cart.find(l=>l.product.sku===product.sku);if(line&&linePrice(line)!=null)$('#manual-price').value=(linePrice(line)/100).toFixed(2);}$('#manual-form').onsubmit=e=>{e.preventDefault();const cents=parseMoney($('#manual-price').value),qty=Number($('#manual-qty').value);if(cents==null||!Number.isInteger(qty)||qty<1||qty>9999){$('#manual-error').textContent='Use a valid price (up to 2 decimal places) and a whole quantity from 1 to 9,999.';return;}const p=product||{sku:'manual:'+crypto.randomUUID(),name:$('#manual-name').value.trim(),category:'Manual items',priceCentavos:null};if(!p.name)return;let line=S.cart.find(l=>l.product.sku===p.sku);if(!line){line={product:p,quantity:qty};S.cart.push(line);}Object.assign(line,{quantity:qty,manualCentavos:cents,observedAt:today()});closeSheet();afterCart('Shelf price saved privately.');};}
async function scan(){dialog('Find it. Scan it. In the basket.',`<p>Use your rear camera to scan the barcode. Camera images stay on this device.</p><div class="scanner-wrap"><video id="camera" playsinline muted aria-label="Live barcode camera"></video><div class="scan-frame"></div><div id="camera-state" class="camera-state">Tap “Start camera” to allow camera access.</div></div><div class="toolbar"><button class="btn primary" data-action="camera-start">${icon('scan')} Start camera</button><button class="btn secondary" id="torch-button" data-action="torch" hidden>${icon('torch')} Torch</button></div><form id="barcode-form" class="searchbox"><label class="sr-only" for="barcode-input">Manual barcode or SKU</label>${icon('scan')}<input id="barcode-input" inputmode="text" placeholder="Or type a barcode / SKU" maxlength="100" required><button type="submit" aria-label="Find barcode">${icon('arrow')}</button></form><div id="scan-result" style="margin-top:15px"><p class="hint">EAN, UPC, Code 128 and QR supported. Search by name from the Shop tab.</p></div>`);$('#barcode-form').onsubmit=e=>{e.preventDefault();lookup($('#barcode-input').value);};}
async function lookup(code){if(!String(code).trim())return;try{const matches=await catalog.lookup(code);if(!$('#sheet').open)await scan();if(matches.length===1){const p=matches[0];lastResult=p;addProduct(p);const {feedback}=await import('./lib/scanner.js');feedback();$('#scan-result').innerHTML=`<div class="last-scan"><span class="tag">ADDED TO YOUR BASKET</span><h3 style="margin:8px 0">${esc(p.name)}</h3><p>${price(p)==null?'Price unavailable — enter the shelf price.':money(price(p))}</p><p class="as-of">${esc(priceDate(p))}</p><div class="toolbar"><button class="btn secondary" data-price="${esc(p.sku)}">Enter shelf price</button><button class="btn secondary" data-tab="cart">View basket</button></div><p class="hint">Scan the next item when you’re ready.</p></div>`;}else if(matches.length>1){$('#scan-result').innerHTML=`<div class="notice">${icon('warning')}<p>This barcode belongs to multiple Hypermart products. Choose the exact item.</p></div>${matches.map(p=>`<button class="scan-choice" data-choose="${esc(p.sku)}">${esc(p.name)}<br><small>SKU ${esc(p.sku)} · ${price(p)==null?'Price unavailable':money(price(p))}</small></button>`).join('')}`;}else{$('#scan-result').innerHTML=`<div class="last-scan"><h3>Not in our catalog.</h3><p class="hint">Barcode ${esc(code)} was not found. Try a product name or add the item privately.</p><div class="toolbar"><button class="btn secondary" data-action="manual">Add manually</button><button class="btn secondary" data-action="report-missing" data-code="${esc(code)}">Save missing-item report</button></div></div>`;}}catch(e){notify(e.message);}}
async function startCamera(){if(!navigator.mediaDevices?.getUserMedia){$('#camera-state').textContent='Camera is unavailable. Use HTTPS or enter a barcode below.';return;}const {Scanner}=await import('./lib/scanner.js');scanner?.stop();scanner=new Scanner($('#camera'),lookup,(state,hasTorch)=>{const el=$('#camera-state');if(!el)return;el.textContent=state==='ready'?'Keep the barcode inside the frame. Tap video to refocus.':state==='denied'?'Camera permission is off. Enable it in your browser’s site settings, then tap Start camera.':'Camera could not start. Close other camera apps or type a barcode below.';$('#torch-button').hidden=!hasTorch;});await scanner.start();}
async function showDetails(sku){const p=catalog.product(catalog.bySku.get(sku));if(!p)return;const d=dialog('A closer look.',`<h3>${esc(p.name)}</h3><p class="hint">Loading source details…</p>`);try{const detail=await catalog.details(sku);d.querySelector('.sheet-body').innerHTML=`<h3>${esc(p.name)}</h3>${[['SKU',sku],['Department',p.department],['Category',p.category],['Subcategory',p.subcategory],['Price',money(price(p))],['Net size',p.size?p.size+' '+p.unit:'Not supplied'],['Brand',p.brand||'Not supplied'],['Live stock','Not supplied'],['Master match',p.masterMatched===false?'Not found · supplied list only':'Matched by SKU'],['Source status',detail?.sourceStatus||'Unknown'],['Barcodes',detail?.barcodes?.join(', ')||'Not supplied']].map(([k,v])=>`<div class="summary-row"><span>${esc(k)}</span><strong style="max-width:65%;overflow-wrap:anywhere;text-align:right">${esc(v)}</strong></div>`).join('')}<p class="as-of">${esc(priceDate(p))}</p><p class="hint">The source status is not a live stock guarantee. Transaction units do not establish net package size.</p><div class="toolbar"><button class="btn primary" data-add="${esc(sku)}">Add to basket</button><button class="btn secondary" data-plan="${esc(sku)}">Save to list</button></div>${warning()}`;}catch(e){d.querySelector('.sheet-body').innerHTML=`<p>${esc(e.message)}</p>`;}}
function finishTrip(){const v=totals(S.cart);if(!v.count)return;dialog('Another good shop, saved.',`<p>${v.count} items · ${money(v.knownCentavos)} known subtotal.</p>${v.unpricedQuantity?`<div class="notice">${icon('warning')}<p><b>This estimate is incomplete.</b>${v.unpricedQuantity} item(s) have no price. You can go back to enter shelf prices, or save the trip with those prices marked unknown.</p></div>`:'<p>This is your device’s estimate. Confirm the final total with your cashier.</p>'}<div class="sheet-actions"><button class="btn secondary" data-action="close-sheet">Back to basket</button><button class="btn primary" data-action="confirm-finish">${v.complete?'Save finished trip':'Save incomplete trip'}</button></div>`);}
function confirmFinish(){const snapshot=structuredClone(S.cart).map(l=>({...l,unitCentavos:linePrice(l)}));S.trips.push({id:crypto.randomUUID(),date:new Date().toISOString(),lines:snapshot,totals:totals(snapshot),budget:S.budget,savingsFound:S.savingsFound,priceAsOf:catalog.priceAsOf});S.cart=[];S.savingsFound=0;save();closeSheet();navigate('trips');notify('Trip saved on this device.');}
function download(name,data,type='application/json'){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function tripText(trip){return `FUJI Grocery Tracker\n${formatDate(trip.date)}\n${trip.totals.count} items\nKnown subtotal: ${money(trip.totals.knownCentavos)}${trip.totals.unpricedQuantity?'\nUnpriced items: '+trip.totals.unpricedQuantity:''}\n${trip.lines.map(l=>l.quantity+' × '+l.product.name+' — '+(linePrice(l)==null?'Unpriced':money(linePrice(l)*l.quantity))).join('\n')}\n${WARNING}`;}
async function shareTrip(id){const trip=S.trips.find(t=>t.id===id);if(!trip)return;const text=tripText(trip);try{if(navigator.share)await navigator.share({title:'My FUJI trip',text});else{await navigator.clipboard.writeText(text);notify('Trip summary copied.');}}catch(e){if(e.name!=='AbortError')download('fuji-trip.txt',text,'text/plain');}}
async function tripImage(id){const trip=S.trips.find(t=>t.id===id);if(!trip)return;const canvas=document.createElement('canvas');canvas.width=1000;canvas.height=650;const ctx=canvas.getContext('2d');ctx.fillStyle='#f7faf8';ctx.fillRect(0,0,1000,650);ctx.fillStyle='#08785b';ctx.fillRect(0,0,1000,12);ctx.font='bold 42px sans-serif';ctx.fillText('FUJI · A little smarter, every shop.',60,110);ctx.fillStyle='#536158';ctx.font='25px sans-serif';ctx.fillText(formatDate(trip.date),60,170);ctx.fillText('Known subtotal',60,260);ctx.fillStyle='#17201d';ctx.font='bold 78px sans-serif';ctx.fillText(money(trip.totals.knownCentavos),60,360);ctx.font='25px sans-serif';ctx.fillText(`${trip.totals.count} items · ${trip.totals.unpricedQuantity} unpriced`,60,420);ctx.fillStyle='#536158';ctx.font='22px sans-serif';ctx.fillText('Prices may not always be accurate. Estimate only.',60,530);ctx.fillText('Final prices are confirmed at the cashier.',60,570);canvas.toBlob(blob=>{const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='fuji-trip-'+trip.date.slice(0,10)+'.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});}
async function ask(question){const q=question.trim();if(!q)return;chat.push({role:'user',text:q});$('#chat-input').value='';$('#chat-log').innerHTML=chatMessages();let answer;const v=totals(S.cart),b=budgetStatus(v.knownCentavos,S.budget),lower=normalizeText(q);if(/budget|badyet|remove|alis|left/.test(lower)){answer=`Your known subtotal is ${money(v.knownCentavos)} for ${v.count} items.${v.unpricedQuantity?' '+v.unpricedQuantity+' item(s) still need a shelf price.':''}\n${S.budget?`Your budget is ${money(S.budget)}. ${b.remaining<0?'You are over by '+money(-b.remaining):'There is '+money(b.remaining)+' left from known prices'}.`:'Set a trip budget from your basket to see how much remains.'}`;if(/remove|alis/.test(lower)&&b.remaining<0){const rescue=allSuggestions().find(s=>s.type==='rescue');if(rescue)answer+='\nYou could review: '+rescue.actions.map(a=>a.name+' ('+money(a.centavos)+')').join('; ')+'. Nothing is removed automatically.';}}else if(/dinner|hapunan/.test(lower)){answer='I can help you find ingredients in the Hypermart catalog, but I cannot promise a priced dinner plan without verified pack sizes, current prices and dietary requirements. Try searching for rice, eggs or vegetables, then confirm their shelf prices.';}else{const term=/rice|bigas/.test(lower)?'rice':lower.replace(/what|whats|cheapest|the|is|ano|ang|mas|mura|find|search|for|please/g,' ').trim();const helperDepartment=term==='rice'?'groceries':department,helperCategory=term==='rice'?'STAPLE':'';await catalog.loadDepartment(helperDepartment).catch(error=>notify(error.message));const matches=catalog.search(term,helperCategory,100,helperDepartment),priced=matches.filter(p=>price(p)!=null).sort((a,b)=>price(a)-price(b));if(priced.length){const p=priced[0];answer=`Lowest pack price among these matching catalog records: ${p.name}, ${money(price(p))}.\n${priceDate(p)}. Pack prices do not establish the cheapest unit price. ${WARNING}`;}else if(matches.length){answer=`I found ${matches.length} matching reference items, including ${matches.slice(0,3).map(p=>p.name+' (SKU '+p.sku+')').join('; ')}.\nThese matching items do not have usable prices, so I cannot truthfully say which is cheapest. Compare shelf prices or ask staff for the latest prices.`;}else answer='I don’t have that item in the loaded catalog results. Try its product name or barcode, or choose a different department. I won’t guess its price.';}
 if(S.aiConsent&&account){try{const token=await accountToken();const r=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+token},body:JSON.stringify({question:q,consent:true,cart:S.cart.map(l=>({sku:l.product.sku,quantity:l.quantity,manualCentavos:l.manualCentavos??null})),budget:S.budget})});if(r.ok){const data=await r.json();answer=data.answer;}else answer+='\n\nThe online helper is unavailable. This answer was prepared on your device.';}catch{answer+='\n\nThe online helper could not connect. Your local helper still works.';}}
 chat.push({role:'assistant',text:answer});if($('#chat-log')){$('#chat-log').innerHTML=chatMessages();$('#chat-log').lastElementChild?.scrollIntoView({block:'nearest',behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'});}}
async function accountToken(){const {getToken}=await import('./lib/account.js');return getToken(account);}
async function showAccount(){const {accountDialog}=await import('./lib/account.js');await accountDialog({dialog,notify,read,write,getState:()=>S,onSignedIn:a=>{account=a;renderPage();},onCloudState:state=>{S={...S,...state};save();renderPage();}});}
function showPrivacy(){dialog('Your shop. Your information.',`<div class="privacy-copy"><p><b>What stays here:</b> your basket, shelf prices, lists, trips and preferences are stored in IndexedDB on this device. Clearing browser storage removes them. Download a backup if you want to keep a copy.</p><p><b>Camera:</b> used only for barcode decoding after your permission. Video and photos are never sent to the server.</p><p><b>Optional account:</b> when configured, signing in allows you to explicitly upload or download a private shopping-data snapshot. It is not automatic and conflicting device copies are not silently merged.</p><p><b>Optional online helper:</b> only after your consent, your question, SKU quantities and budget may be sent to the configured server and its AI provider. Provider free tiers may use submitted data for improvement. Do not enter personal or sensitive information. The default helper works on this device.</p><p><b>Reports:</b> missing-item reports stay on this device until you export them. No automatic telemetry, ads or analytics are collected.</p><p><b>Your choices:</b> turn off AI sharing, export your data, or use Delete my data. If signed in, delete the cloud snapshot first. The store must provide its privacy contact and retention policy before enabling online features for public use.</p><p>This notice follows data-minimization principles. The store remains responsible for its obligations under the Philippines Data Privacy Act of 2012 (RA 10173).</p></div>`);}
async function poster(){const {toDataURL}=await import('./vendor/qr.js');const url=new URL('./',location.href).href.split('#')[0],data=await toDataURL(url,{width:420,margin:2,color:{dark:'#065f46',light:'#ffffff'}});dialog('A little smarter, every shop.',`<div class="poster"><p class="eyebrow">FUJI GROCERY TRACKER</p><h2>Scan. Plan. Keep track.</h2><img src="${data}" alt="QR code linking to ${esc(url)}" style="width:240px;max-width:100%;height:auto"><p>${esc(url)}</p><p class="hint">iPhone: Share → Add to Home Screen.<br>Android Chrome: menu → Install app / Add to Home Screen.</p><p class="hint">${esc(WARNING)}</p></div><button class="btn primary full" data-action="print">Print poster</button>`);}
async function action(name,button){
 if(name==='close-sheet')closeSheet();
 if(name==='budget')showBudget();
 if(name==='scan')scan();
 if(name==='camera-start')startCamera();
 if(name==='torch'){torch=!torch;try{await scanner?.torch(torch);}catch{notify('Torch is not supported by this camera.');}}
 if(name==='theme'){S.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';applyTheme();save();shell();}
 if(name==='history')navigate('trips');
 if(name==='view-basket'){closeSheet();navigate('cart');}
 if(name==='manual')showManual();
 if(name==='lookup-search'){const code=$('#product-search')?.value;if(code){await scan();await lookup(code);}else scan();}
 if(name==='more-products'){searchLimit+=24;renderProducts();}
 if(name==='finish')finishTrip();
 if(name==='confirm-finish')confirmFinish();
 if(name==='new-list'){dialog('A fresh list.',`<form id="new-list-form"><label class="field">List name<input id="list-name" maxlength="60" required placeholder="Weekly essentials"></label><button class="btn primary full" type="submit">Create list</button></form>`);$('#new-list-form').onsubmit=e=>{e.preventDefault();const list={id:crypto.randomUUID(),name:$('#list-name').value.trim(),items:[]};if(!list.name)return;S.lists.push(list);S.activeList=list.id;save();closeSheet();renderPage();};}
 if(name==='list-to-cart'){const items=currentList().items.filter(l=>!l.checked);for(const l of items){const existing=S.cart.find(c=>c.product.sku===l.product.sku);if(!existing)S.cart.push({product:l.product,quantity:1,manualCentavos:null});}afterCart('Unchecked items are in your basket.');}
 if(name==='export')download('fuji-trips.csv','\uFEFF'+tripCsv(S.trips),'text/csv;charset=utf-8');
 if(name==='backup')download('fuji-shopper-backup.json',JSON.stringify({schemaVersion:1,exportedAt:new Date().toISOString(),data:S},null,2));
 if(name==='privacy')showPrivacy();
 if(name==='account')showAccount();
 if(name==='refresh'){button.disabled=true;try{await catalog.refreshPrices();for(const l of S.cart){const p=catalog.product(catalog.bySku.get(l.product.sku));if(p)l.product=p;}save();renderPage();notify('Checked for new published prices.');}catch(e){notify(e.message);}finally{button.disabled=false;}}
 if(name==='download-offline'){button.disabled=true;try{await catalog.downloadAll((n,total)=>{const p=$('#offline-progress');if(p)p.textContent=`Downloading ${n} of ${total} catalog files…`;});$('#offline-progress').textContent='Full Hypermart reference catalog saved for offline lookup.';notify('Your full catalog is ready offline.');}catch(e){notify(e.message);}finally{button.disabled=false;}}
 if(name==='install'){if(installPrompt){await installPrompt.prompt();installPrompt=null;}else dialog('FUJI, one tap away.',`<p><b>iPhone / iPad:</b> open FUJI in Safari, tap Share, then Add to Home Screen.</p><p><b>Android:</b> open FUJI in Chrome, tap the browser menu, then Install app or Add to Home Screen.</p><p>Download the full catalog in Settings for offline lookup. HTTPS is needed for camera access and installation.</p>`);}
 if(name==='delete'){dialog('Delete your shopper data?',`<p>This deletes your basket, lists, trips, account session, preferences and cached catalog on this device. Download a backup first if you want to keep them.${account?' A cloud snapshot may exist; delete it from Account first.':''}</p><div class="sheet-actions"><button class="btn secondary" data-action="close-sheet">Keep my data</button><button class="btn danger" data-action="confirm-delete">Delete device data</button></div>`);}
 if(name==='confirm-delete'){await deleteLocalData();location.reload();}
 if(name==='report-missing'){const reports=await read('missing')||[];if(reports.length<1000)reports.push({barcode:button.dataset.code,date:today()});await write('missing',reports);notify('Missing-item report saved on this device.');}
 if(name==='poster')poster();
 if(name==='print')window.print();
}
document.addEventListener('click',async e=>{
 const b=e.target.closest('button,[data-tab]');if(!b||b.disabled)return;
 try{
 if(b.dataset.tab){closeSheet();navigate(b.dataset.tab);}
 else if(b.dataset.action)await action(b.dataset.action,b);
 else if(b.hasAttribute('data-category')){category=b.dataset.category;searchLimit=24;renderPage();}
 else if(b.dataset.add){const p=catalog.product(catalog.bySku.get(b.dataset.add));if(p)addProduct(p);}
 else if(b.dataset.plan){const p=catalog.product(catalog.bySku.get(b.dataset.plan));if(p&&!currentList().items.some(l=>l.product.sku===p.sku)){currentList().items.push({product:p,checked:false});save();notify('Saved to '+currentList().name+'.');}}
 else if(b.dataset.detail)showDetails(b.dataset.detail);
 else if(b.dataset.price){const p=S.cart.find(l=>l.product.sku===b.dataset.price)?.product;if(p)showManual(p);}
 else if(b.dataset.choose){const p=catalog.product(catalog.bySku.get(b.dataset.choose));if(p){addProduct(p);notify('Exact item added to basket.');}}
 else if(b.dataset.qty){const l=S.cart.find(l=>l.product.sku===b.dataset.sku);if(l){const n=l.quantity+Number(b.dataset.qty);if(n<1)removeLine(l.product.sku);else if(n<=9999){l.quantity=n;afterCart();}}}
 else if(b.dataset.remove)removeLine(b.dataset.remove);
 else if(b.dataset.listRemove){currentList().items=currentList().items.filter(l=>l.product.sku!==b.dataset.listRemove);save();renderPage();}
 else if(b.dataset.preset)$('#budget-input').value=b.dataset.preset;
 else if(b.dataset.dismiss){S.dismissed.push(b.dataset.dismiss);save();renderPage();}
 else if(b.dataset.swap){const s=allSuggestions()[Number(b.dataset.swap)],l=S.cart.find(l=>l.product.sku===s?.from?.sku);if(s&&l&&s.savedCentavos>0){const before=structuredClone(S.cart);S.cart=S.cart.filter(x=>x!==l);const existing=S.cart.find(x=>x.product.sku===s.target.sku);if(existing){if(existing.quantity+s.quantity>9999){S.cart=before;notify('This swap would exceed the quantity limit.');return;}existing.quantity+=s.quantity;}else S.cart.push({product:s.target,quantity:s.quantity,manualCentavos:null});S.savingsFound+=s.savedCentavos;save();renderPage();notify('Swap applied. Estimated saving '+money(s.savedCentavos),()=>{S.cart=before;S.savingsFound-=s.savedCentavos;save();renderPage();});}}
 else if(b.dataset.trip){const trip=S.trips.find(t=>t.id===b.dataset.trip);dialog('Your saved trip',`<p>${formatDate(trip.date)} · ${money(trip.totals.knownCentavos)} known subtotal</p>${trip.lines.map(l=>`<div class="summary-row"><span>${l.quantity} × ${esc(l.product.name)}<small class="as-of">${l.manualCentavos!=null?'Shelf price entered '+esc(l.observedAt):esc(priceDate(l.product))}</small></span><strong>${linePrice(l)==null?'Unpriced':money(linePrice(l)*l.quantity)}</strong></div>`).join('')}${warning()}`);}
 else if(b.dataset.share)shareTrip(b.dataset.share);
 else if(b.dataset.image)tripImage(b.dataset.image);
 else if(b.dataset.prompt)ask(b.dataset.prompt);
 }catch(error){notify(error.message||'That action could not be completed.');}
});
function removeLine(sku){const index=S.cart.findIndex(l=>l.product.sku===sku);if(index<0)return;const [removed]=S.cart.splice(index,1);save();renderPage();notify('Item removed.',()=>{S.cart.splice(index,0,removed);save();renderPage();});}
document.addEventListener('input',e=>{const el=e.target;if(el.id==='product-search'){query=el.value;searchLimit=24;clearTimeout(searchTimer);searchTimer=setTimeout(renderProducts,160);}if(el.dataset.note){const l=S.cart.find(l=>l.product.sku===el.dataset.note);if(l){l.note=el.value;save();}}});
document.addEventListener('change',async e=>{const el=e.target;if(el.id==='theme-select'){S.theme=el.value;applyTheme();save();}if(el.id==='language-select'){S.language=el.value;applyTheme();save();shell();}if(el.id==='ai-consent'){S.aiConsent=el.checked;save();}if(el.id==='list-select'){S.activeList=el.value;save();renderPage();}if(el.id==='category-filter'){category=el.value;renderPage();}if(el.id==='department-filter'){department=el.value;category='';el.disabled=true;notify('Opening department catalog…');try{await catalog.loadDepartment(department);renderPage();}catch(err){department='groceries';notify(err.message);renderPage();}}if(el.dataset.check){const l=S.cart.find(l=>l.product.sku===el.dataset.check);if(l){l.checked=el.checked;save();renderPage();}}if(el.dataset.listCheck){const l=currentList().items.find(l=>l.product.sku===el.dataset.listCheck);if(l){l.checked=el.checked;save();renderPage();}}});
document.addEventListener('submit',e=>{if(e.target.id==='chat-form'){e.preventDefault();ask($('#chat-input').value);}});
$('#sheet').addEventListener('close',()=>{scanner?.stop();scanner=null;});
$('#sheet').addEventListener('cancel',()=>{scanner?.stop();scanner=null;});
$('#sheet').addEventListener('click',e=>{if(e.target.id==='camera')scanner?.focus();});
let touchStart=null;document.addEventListener('touchstart',e=>{const row=e.target.closest('[data-cart-sku]');if(row&&!e.target.closest('button,input'))touchStart={x:e.touches[0].clientX,y:e.touches[0].clientY,sku:row.dataset.cartSku};},{passive:true});document.addEventListener('touchend',e=>{if(touchStart){const p=e.changedTouches[0];if(p.clientX-touchStart.x < -100&&Math.abs(p.clientY-touchStart.y)<50)removeLine(touchStart.sku);touchStart=null;}},{passive:true});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});
window.addEventListener('online',()=>{const c=$('#connection');if(c){c.classList.remove('offline');c.innerHTML='<span class="status-dot"></span>Ready to shop';}});
window.addEventListener('offline',()=>{const c=$('#connection');if(c){c.classList.add('offline');c.innerHTML='<span class="status-dot"></span>Offline mode';}});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(navKeys.includes(next)&&next!==tab){tab=next;renderPage();}});
matchMedia('(prefers-color-scheme:dark)').addEventListener('change',()=>{if(S.theme==='system')applyTheme();});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&scanner){scanner.stop();const label=$('#camera-state');if(label)label.textContent='Camera paused. Tap Start camera to continue.';}});
async function init(){try{const saved=await read('user');if(saved)S={...S,...saved};if(!S.lists.length)S.lists=[{id:'next',name:'My next shop',items:[]}];applyTheme();await catalog.init({quick:true});department=catalog.meta.defaultDepartment||'groceries';account=await read('account');const hash=location.hash.slice(1);if(navKeys.includes(hash))tab=hash;lastBudgetState=budgetStatus(totals(S.cart).knownCentavos,S.budget).state;shell();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js',{scope:'./'}).catch(()=>notify('Offline app installation could not be enabled.'));if(!S.welcomed)showBudget(true);}catch(e){$('#app').innerHTML=`<div class="initial-loading"><span class="brand-symbol">F<span>•</span></span><h1>Let’s get you connected.</h1><p>${esc(e.message)}</p><button class="btn primary" id="retry-load">Try again</button></div>`;$('#retry-load').onclick=()=>location.reload();}}
init();
